INSERT INTO books (title, author, isbn, publisher, publication_year, category, description, quantity, available_quantity)
VALUES
  ('活着', '余华', '9787506365437', '作家出版社', 2012, '文学', '《活着》是余华的代表作之一，讲述了在大时代背景下，随着内战、三反五反、大跃进、文化大革命等社会变革，徐福贵的人生和家庭不断经受着苦难，到了最后所有亲人都先后离他而去，仅剩下他和一头老牛相依为命。', 5, 5),
  ('三体', '刘慈欣', '9787536692930', '重庆出版社', 2008, '科幻', '《三体》是刘慈欣创作的系列长篇科幻小说，由《三体》、《三体Ⅱ·黑暗森林》、《三体Ⅲ·死神永生》组成。第一部讲述了文化大革命如火如荼进行的同时，军方探寻外星文明的绝秘计划"红岸工程"取得了突破性进展。', 8, 6),
  ('围城', '钱钟书', '9787020024759', '人民文学出版社', 1991, '文学', '《围城》是钱钟书所著的长篇小说，是中国现代文学史上一部风格独特的讽刺小说。被誉为"新儒林外史"。', 4, 3),
  ('平凡的世界', '路遥', '9787020049295', '人民文学出版社', 2005, '文学', '《平凡的世界》是一部现实主义小说，也是小说化的家族史。作家高度浓缩了中国西北农村的历史变迁过程，作品达到了思想性与艺术性的高度统一。', 6, 5),
  ('明朝那些事儿', '当年明月', '9787807592097', '中国友谊出版公司', 2009, '历史', '《明朝那些事儿》主要讲述的是从1344年到1644年这三百年间关于明朝的一些故事。以史料为基础，以年代和具体人物为主线，并加入了小说的笔法，对明朝十七帝和其他王公权贵和小人物的命运进行全景展示。', 10, 8),
  ('万历十五年', '黄仁宇', '9787108009821', '生活·读书·新知三联书店', 2007, '历史', '《万历十五年》是黄仁宇创作的历史学著作，首次刊行于1981年。这本书的特别之处在于，它选择了万历十五年这样一个看似平凡的年份，通过剖析这一年发生的种种看似无关紧要的事件，揭示了明王朝走向衰落的深层原因。', 3, 2),
  ('乌合之众', '古斯塔夫·勒庞', '9787100034769', '中央编译出版社', 2004, '心理学', '《乌合之众：大众心理研究》是法国社会心理学家古斯塔夫·勒庞创作的社会心理学著作，首次出版于1895年。', 5, 4),
  ('思考，快与慢', '丹尼尔·卡尼曼', '9787508647354', '中信出版社', 2012, '心理学', '《思考，快与慢》是2002年诺贝尔经济学奖得主丹尼尔·卡尼曼的代表作，该书被认为是社会思想的一部里程碑式著作，堪与亚当·斯密的《国富论》和西格蒙德·弗洛伊德的《梦的解析》相媲美。', 4, 4),
  ('黑客与画家', '保罗·格雷厄姆', '9787115266144', '人民邮电出版社', 2011, '科技', '《黑客与画家》是硅谷创业之父保罗·格雷厄姆的文集，主要介绍黑客即优秀程序员的爱好和动机，讨论黑客成长、黑客对世界的贡献以及编程语言和黑客工作方法等所有对计算机时代感兴趣的人的一些话题。', 6, 5),
  ('代码整洁之道', 'Robert C. Martin', '9787115216878', '人民邮电出版社', 2010, '科技', '《代码整洁之道》讲述了一系列行之有效的整洁代码操作实践。书中介绍的规则均来自作者多年的实践经验，涵盖从命名到重构的多个编程方面。', 7, 6),
  ('经济学原理', 'N.格里高利·曼昆', '9787300162517', '北京大学出版社', 2012, '经济', '《经济学原理》是美国经济学家N.格里高利·曼昆创作的经济学著作，首次出版于1998年。该书主要介绍了经济学十大原理，这十大原理贯穿于书中始末，并运用它们对贸易、供求关系、消费与生产、企业行为与产业组织、劳动力市场以及宏观经济学理论进行阐述。', 5, 3),
  ('富爸爸穷爸爸', '罗伯特·清崎', '9787500650152', '南海出版公司', 2000, '经济', '《富爸爸穷爸爸》是一个真实的故事，作者罗伯特·清崎的亲生父亲和朋友的父亲对金钱的看法截然不同，这使他对认识金钱产生了兴趣，最终他接受了朋友的父亲的建议，也就是书中所说的"富爸爸"的观念。', 8, 7),
  ('苏菲的世界', '乔斯坦·贾德', '9787532725367', '作家出版社', 1996, '哲学', '《苏菲的世界》是挪威作家乔斯坦·贾德创作的一本关于西方哲学史的长篇小说，它以小说的形式，通过一名哲学导师向一个叫苏菲的女孩传授哲学知识的经过，揭示了西方哲学史发展的历程。', 4, 4),
  ('中国哲学简史', '冯友兰', '9787300034753', '北京大学出版社', 1985, '哲学', '《中国哲学简史》是冯友兰先生于1947年在美国宾夕法尼亚大学讲授中国哲学史的英文讲稿，后经整理于1948年由麦克米伦公司出版。此书是迄今西方人了解、研究中国哲学的最佳入门书。', 3, 2),
  ('如何阅读一本书', '莫提默·J. 艾德勒', '9787108010407', '商务印书馆', 2004, '教育', '《如何阅读一本书》是一本阅读指南，介绍了阅读的方法、技巧，阅读所应具备的广阔视野。自1940年问世以来，在西方世界好评甚多，重版多次。', 6, 5),
  ('刻意练习', '安德斯·艾利克森', '9787111544937', '机械工业出版社', 2016, '教育', '《刻意练习：如何从新手到大师》是2016年11月机械工业出版社出版的图书，作者是安德斯·艾利克森。该书告诉我们，天才的"天才"不是与生俱来的，而是经过后天的刻意练习形成的。', 5, 4),
  ('乔布斯传', '沃尔特·艾萨克森', '9787508634049', '中信出版社', 2011, '传记', '《史蒂夫·乔布斯传》是乔布斯唯一授权的官方传记，由著名作家沃尔特·艾萨克森在过去两年与乔布斯面对面交流40多次、对乔布斯100多位家庭成员、朋友、竞争对手和同事的采访的基础上撰写而成。', 4, 3),
  ('人类群星闪耀时', '斯蒂芬·茨威格', '9787100048972', '商务印书馆', 2004, '传记', '《人类群星闪耀时》是奥地利作家斯蒂芬·茨威格创作的历史传记文集，书中截取了拿破仑、歌德、托尔斯泰、列宁等12位伟人的历史性时刻，以独特的视角，展现了14个决定世界历史的瞬间。', 5, 4),
  ('艺术的故事', '贡布里希', '9787535607184', '湖南美术出版社', 2008, '艺术', '《艺术的故事》是贡布里希爵士编著的西方艺术史，该书概括地叙述了从最早的洞窟绘画到当今的实验艺术的发展历程，阐明艺术史是"各种传统不断迂回、不断改变的历史"。', 3, 2),
  ('美的历程', '李泽厚', '9787108021021', '生活·读书·新知三联书店', 2009, '艺术', '《美的历程》是中国美学的经典之作，从宏观鸟瞰角度对中国数千年的艺术、文学作了概括描述和美学把握。', 4, 3),
  ('百年孤独', '加西亚·马尔克斯', '9787544253994', '南海出版公司', 2011, '小说', '《百年孤独》是哥伦比亚作家加西亚·马尔克斯创作的长篇小说，是其代表作，也是拉丁美洲魔幻现实主义文学的代表作，被誉为"再现拉丁美洲历史社会图景的鸿篇巨著"。', 6, 5),
  ('1984', '乔治·奥威尔', '9787532741855', '上海译文出版社', 2008, '小说', '《1984》是英国作家乔治·奥威尔创作的一部反乌托邦小说，出版于1949年。该小说刻画了一个令人感到窒息和恐怖的、以追逐权力为最终目标的假想的极权主义社会。', 5, 4),
  ('小王子', '安托万·德·圣埃克苏佩里', '9787544258012', '南海出版公司', 2013, '小说', '《小王子》是法国作家安托万·德·圣埃克苏佩里于1942年写成的著名儿童文学短篇小说。本书的主人公是来自外星球的小王子。', 10, 9),
  ('时间简史', '斯蒂芬·霍金', '9787535732309', '湖南科学技术出版社', 2002, '科学', '《时间简史》是英国物理学家斯蒂芬·霍金创作的科学著作，首版时间是1988年。该书是一部将高深的理论物理通俗化的科普范本，讲述了探索时间和空间核心秘密的故事。', 4, 3),
  ('人类简史', '尤瓦尔·赫拉利', '9787508647357', '中信出版社', 2014, '科学', '《人类简史：从动物到上帝》是以色列新锐历史学家的一部重磅作品。从认知革命、农业革命到科学革命，我们真的了解自己吗？我们过得更加快乐吗？', 6, 5);
